CREATE TABLE pesanan (id INTEGER PRIMARY KEY, toko_id INTEGER NOT NULL, total INTEGER NOT NULL, dibuat TEXT NOT NULL);
WITH RECURSIVE g(x) AS (SELECT 1 UNION ALL SELECT x + 1 FROM g WHERE x < 20000)
INSERT INTO pesanan SELECT x, 1 + (x % 50), 35000, datetime('2026-01-01', '+' || (x * 1570) || ' seconds') FROM g;
